UserObject.plantUmlData:
{
  "data": "@startuml
|Người luyện tập|
start

:Truy cập trang chủ;
:Chọn "Đăng ký";

if (Đã có tài khoản?) then (Có)
    :Chọn "Đăng nhập ngay";
    :Chuyển sang Đăng nhập (UC2);
    stop
else (Không)
    :Nhập thông tin đăng ký;
    :Bấm "Tạo tài khoản";
endif

|Hệ thống|
:Kiểm tra tính hợp lệ dữ liệu;

if (Dữ liệu hợp lệ?) then (Không)
    :Hiển thị lỗi;
    |Người luyện tập|
    :Sửa thông tin;
    :Bấm "Tạo tài khoản";
    |Hệ thống|
    :Kiểm tra lại dữ liệu;
else (Có)
endif

if (Mật khẩu khớp?) then (Không)
    :Hiển thị "Mật khẩu nhập lại không trùng khớp";
    |Người luyện tập|
    :Nhập lại mật khẩu;
    :Bấm "Tạo tài khoản";
    |Hệ thống|
    :Kiểm tra lại dữ liệu;
else (Có)
endif

:Kiểm tra Email;

if (Email đã tồn tại?) then (Có)
    :Hiển thị "Email này đã được sử dụng";
    |Người luyện tập|
    :Nhập email khác;
    :Bấm "Tạo tài khoản";
    |Hệ thống|
    :Kiểm tra lại Email;
else (Chưa)
endif

:Mã hóa mật khẩu;
:Tạo tài khoản;
:Thông báo "Đăng ký thành công";

|Người luyện tập|
:Chuyển sang Đăng nhập (UC2);

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Người luyện tập / Admin|
start

:Chọn "Đăng nhập";

|Hệ thống|
:Hiển thị màn hình đăng nhập;

|Người luyện tập / Admin|
:Nhập Email và Mật khẩu;
:Chọn "Đăng nhập";

|Hệ thống|
:Kiểm tra thông tin tài khoản;

if (Tài khoản bị khóa?) then (Có)
    :Thông báo tài khoản bị tạm khóa;
    stop
else (Không)
endif

if (Thông tin chính xác?) then (Không)
    :Thông báo "Email hoặc mật khẩu không chính xác";
    |Người luyện tập / Admin|
    :Nhập lại thông tin;
    |Hệ thống|
    :Kiểm tra lại;
else (Có)
endif

:Khởi tạo phiên đăng nhập;

if (Vai trò?) then (Candidate)
    :Chuyển đến Dashboard / Luyện tập;
else (Admin)
    :Chuyển đến trang Quản trị;
endif

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Người luyện tập|
start

:Chọn "Ngân hàng câu hỏi" / "Bắt đầu luyện tập";

|Hệ thống|
:Hiển thị danh sách câu hỏi;

|Người luyện tập|
:Chọn bộ lọc / tìm kiếm;

|Hệ thống|
:Cập nhật danh sách câu hỏi;

if (Có câu hỏi phù hợp?) then (Không)
    :Thông báo "Không tìm thấy câu hỏi phù hợp";
    |Người luyện tập|
    :Xóa bộ lọc;
    |Hệ thống|
    :Hiển thị lại danh sách;
else (Có)
endif

|Người luyện tập|
if (Chọn ngẫu nhiên?) then (Có)
    |Hệ thống|
    :Tự động chọn câu hỏi ngẫu nhiên;
else (Không)
    :Chọn một câu hỏi;
endif

|Hệ thống|
:Hiển thị chi tiết câu hỏi;
:Chuyển sang Ghi âm câu trả lời (UC4);

stop
@enduml
",
  "config": null
}

{
  "data": "@startuml
|Người luyện tập|
start

:Nhấn "Bắt đầu ghi âm";

|Hệ thống|
:Yêu cầu quyền Microphone;

if (Cho phép Microphone?) then (Không)
    :Hiển thị hướng dẫn bật quyền Microphone;
    stop
else (Có)
endif

:Hiển thị đồng hồ ghi âm;

|Người luyện tập|
:Trả lời câu hỏi;
:Nhấn "Hoàn thành / Dừng ghi âm";

|Hệ thống|
:Hiển thị bản ghi và các lựa chọn;

if (Ghi âm lại?) then (Có)
    :Xóa bản ghi tạm thời;
    |Người luyện tập|
    :Nhấn "Bắt đầu ghi âm";
    |Hệ thống|
    :Ghi âm lại;
else (Không)
    if (Hủy bỏ?) then (Có)
        :Quay về danh sách câu hỏi;
        stop
    else (Không)
        |Người luyện tập|
        :Nhấn "Nộp bài chấm điểm";
        |Hệ thống|
        :Tải file âm thanh lên Server;
        :Chuyển sang UC5;
    endif
endif

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Hệ thống|
start

:Nhận file âm thanh từ UC4;
:Gửi file tới Speech-to-Text;

if (STT nhận diện được?) then (Không)
    :Báo lỗi "Không nhận diện được giọng nói";
    stop
else (Có)
endif

:Nhận Transcript;
:Phân tích tốc độ nói và từ đệm;

:Gửi Transcript và câu hỏi tới LLM;

if (LLM phản hồi?) then (Không)
    :Thông báo lỗi;
    |Người luyện tập|
    :Thử lại;
    |Hệ thống|
    :Gửi lại yêu cầu LLM;
else (Có)
endif

:Tổng hợp điểm số;
:Lưu kết quả vào Database;
:Hiển thị bảng điểm và nhận xét;

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Người luyện tập|
start

:Tại màn hình kết quả;
:Nhấn "Nghe AI nhận xét";

|Hệ thống|
:Lấy nội dung nhận xét;
:Gửi nội dung tới TTS;

if (TTS hoạt động?) then (Không)
    :Thông báo lỗi TTS;
    :Giữ hiển thị nhận xét dạng văn bản;
    stop
else (Có)
endif

:TTS tạo âm thanh;
:Phát giọng đọc AI;

|Người luyện tập|
:Pause / Play / Điều chỉnh âm lượng;

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Người luyện tập|
start

:Chọn "Lịch sử luyện tập";

|Hệ thống|
:Truy vấn Database;

if (Có lịch sử?) then (Không)
    :Hiển thị lịch sử trống;
    |Người luyện tập|
    :Chọn "Chọn câu hỏi";
    :Chuyển sang UC3;
    stop
else (Có)
endif

:Hệ thống hiển thị danh sách lịch sử;

|Người luyện tập|
:Chọn bài luyện tập;

|Hệ thống|
:Hiển thị chi tiết bài luyện tập;

if (File ghi âm còn hoạt động?) then (Không)
    :Thông báo không tải được Audio;
    :Vẫn hiển thị Transcript và điểm số;
else (Có)
    :Cho phép phát lại bản ghi âm;
endif

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Admin|
start

:Truy cập "Quản lý câu hỏi";

|Hệ thống|
:Hiển thị danh sách câu hỏi;

|Admin|
if (Thao tác?) then (Thêm)
    :Nhập thông tin câu hỏi;
    :Bấm "Lưu";

elseif (Sửa)
    :Chọn câu hỏi;
    :Cập nhật thông tin;
    :Bấm "Cập nhật";

else (Xóa)
    :Chọn câu hỏi;
    :Nhấn "Xóa";
    :Xác nhận xóa;
endif

|Hệ thống|
:Kiểm tra dữ liệu;

if (Dữ liệu hợp lệ?) then (Không)
    :Thông báo lỗi;
    |Admin|
    :Bổ sung / sửa thông tin;
    stop
else (Có)
endif

if (Đang xóa câu hỏi?) then (Có)
    if (Đã được dùng trong lịch sử?) then (Có)
        :Chuyển trạng thái sang "Ẩn";
    else (Không)
        :Xóa câu hỏi;
    endif
else (Không)
    :Cập nhật Database;
endif

:Thông báo thao tác thành công;
:Tải lại danh sách câu hỏi;

stop
@enduml",
  "config": null
}

{
  "data": "@startuml
|Admin|
start

:Truy cập "Thống kê người dùng";

|Hệ thống|
:Tổng hợp dữ liệu;
:Hiển thị Dashboard thống kê;

|Admin|
:Chọn khoảng thời gian;

|Hệ thống|
:Cập nhật thống kê;

if (Có dữ liệu?) then (Không)
    :Hiển thị dữ liệu trống;
    :Đồ thị ở mức 0;
else (Có)
    :Hiển thị dữ liệu thống kê;
endif

|Admin|
if (Chọn người dùng?) then (Có)
    :Chọn một người dùng;
    |Hệ thống|
    :Hiển thị chi tiết hoạt động;
else (Không)
endif

|Admin|
if (Xuất báo cáo?) then (Có)
    :Chọn Excel / CSV;
    |Hệ thống|
    :Xuất báo cáo;
else (Không)
endif

stop
@enduml",
  "config": null
}
